package com.campusconnect.controller;
import javafx.fxml.FXMLLoader; import javafx.scene.*; import javafx.scene.control.*; import javafx.stage.Stage;
public final class UiUtil { private UiUtil(){} public static void scene(Node from,String fxml){try{Scene s=new Scene(FXMLLoader.load(UiUtil.class.getResource("/fxml/"+fxml)),1100,700);s.getStylesheets().add(UiUtil.class.getResource("/css/style.css").toExternalForm());Stage st=(Stage)from.getScene().getWindow();st.setScene(s);}catch(Exception e){alert("Navigation error",e.getMessage());}} public static void alert(String title,String msg){new Alert(Alert.AlertType.INFORMATION,title,msg,ButtonType.OK).showAndWait();} public static void error(String msg){new Alert(Alert.AlertType.ERROR,"CampusConnect",msg,ButtonType.OK).showAndWait();} public static boolean confirm(String msg){return new Alert(Alert.AlertType.CONFIRMATION,"CampusConnect",msg,ButtonType.YES,ButtonType.NO).showAndWait().orElse(ButtonType.NO)==ButtonType.YES;} }
